static uint32_t level_color(int level)
{
    if (level >= 2) {
        return C_RED;
    }
    if (level == 1) {
        return C_AMBER;
    }
    return C_GREEN;
}

static int clamp100(float v)
{
    if (v < 0.0f) {
        return 0;
    }
    if (v > 100.0f) {
        return 100;
    }
    return (int)(v + 0.5f);
}

static void fmt_rate(float kb, char *buf, size_t n)
{
    if (kb >= 1024.0f) {
        snprintf(buf, n, "%.1fM", (double)(kb / 1024.0f));
    } else {
        snprintf(buf, n, "%.0fK", (double)kb);
    }
}

static void fmt_uptime(long sec, char *buf, size_t n)
{
    if (sec < 0) {
        sec = 0;
    }
    long d = sec / 86400;
    long h = (sec % 86400) / 3600;
    long m = (sec % 3600) / 60;
    long s = sec % 60;
    snprintf(buf, n, "%ldd %02ld:%02ld:%02ld", d, h, m, s);
}

// Formats a label through newlib's snprintf. LVGL's own sprintf is built without
// float support (CONFIG_LV_USE_FLOAT is off), so "%f" in lv_label_set_text_fmt
// renders as garbage; going through snprintf keeps float fields correct.
static void label_printf(lv_obj_t *lbl, const char *fmt, ...)
{
    char buf[48];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    lv_label_set_text(lbl, buf);
}

static lv_obj_t *make_label(lv_obj_t *parent, const char *text,
                            const lv_font_t *font, uint32_t color)
{
    lv_obj_t *lbl = lv_label_create(parent);
    lv_label_set_text(lbl, text);
    lv_obj_set_style_text_font(lbl, font, 0);
    lv_obj_set_style_text_color(lbl, lv_color_hex(color), 0);
    return lbl;
}

static lv_obj_t *put_label(lv_obj_t *parent, const char *text, int x, int y,
                           const lv_font_t *font, uint32_t color)
{
    lv_obj_t *lbl = make_label(parent, text, font, color);
    lv_obj_set_pos(lbl, x, y);
    return lbl;
}

static lv_obj_t *make_container(lv_obj_t *parent, int x, int y, int w, int h)
{
    lv_obj_t *c = lv_obj_create(parent);
    lv_obj_set_size(c, w, h);
    lv_obj_set_pos(c, x, y);
    lv_obj_set_style_bg_opa(c, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(c, 0, 0);
    lv_obj_set_style_pad_all(c, 0, 0);
    lv_obj_clear_flag(c, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_clear_flag(c, LV_OBJ_FLAG_CLICKABLE);
    return c;
}

static lv_obj_t *make_bar(lv_obj_t *parent, int x, int y, int w, int h,
                          uint32_t color)
{
    lv_obj_t *bar = lv_bar_create(parent);
    lv_obj_set_size(bar, w, h);
    lv_obj_set_pos(bar, x, y);
    lv_bar_set_range(bar, 0, 100);
    lv_bar_set_value(bar, 0, LV_ANIM_OFF);
    lv_obj_clear_flag(bar, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_style_radius(bar, 3, LV_PART_MAIN);
    lv_obj_set_style_radius(bar, 3, LV_PART_INDICATOR);
    lv_obj_set_style_bg_color(bar, lv_color_hex(C_DIM), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_bg_color(bar, lv_color_hex(color), LV_PART_INDICATOR);
    lv_obj_set_style_bg_grad_dir(bar, LV_GRAD_DIR_NONE, LV_PART_INDICATOR);
    return bar;
}

static lv_obj_t *make_arc(lv_obj_t *parent, int x, int y, int size, uint32_t color)
{
    lv_obj_t *arc = lv_arc_create(parent);
    lv_obj_set_size(arc, size, size);
    lv_obj_set_pos(arc, x, y);
    lv_arc_set_rotation(arc, 135);
    lv_arc_set_bg_angles(arc, 0, 270);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, 0);
    lv_obj_remove_style(arc, NULL, LV_PART_KNOB);
    lv_obj_clear_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_style_arc_width(arc, 10, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 10, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(C_DIM), LV_PART_MAIN);
    lv_obj_set_style_arc_color(arc, lv_color_hex(color), LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
    return arc;
}

static void set_text_clipped(lv_obj_t *lbl, const char *text, int max_chars)
{
    char buf[PCMON_CMODEL_MAX + 1];
    size_t cap = sizeof(buf) - 1;
    if ((size_t)max_chars < cap) {
        cap = (size_t)max_chars;
    }
    if (!text) {
        text = "--";
    }
    strncpy(buf, text, cap);
    buf[cap] = '\0';
    lv_label_set_text(lbl, buf);
}

